@pytest.mark.parametrize("mode", [ pytest.param("intact", id="ref_only_file_intact"), pytest.param("corrupt", id="file_corrupt_ref_dropped"), pytest.param("missing", id="file_and_ref_deleted_selfconsistent"), ]) def test_c02_single_ref_variants_refused(tmp_path: Path, mode: str) -> None: """C02 主反例(复审 R2 §4 single_ref_missing 三变体):对已完成 expand 任务的 production_report —— ①仅删 manifest 引用(文件在); ②文件改坏 + 删引用;③**文件与引用一起删 + 自洽重算新 digest** (DB/native 均不改)⇒ 读取一律先结构化拒(必要集合闭合;③由 原生实际消费闭合捕获,不再被"枚举时文件不存在=合法缺席"放过); 零业务写、原 payload/native 权威/缺席形态保全、还原正控通过。""" run_id = f"c02r2-{mode}" runs_root, out = _full_fixture(tmp_path, run_id) ledger = ledger_for(runs_root, run_id) digest = out["native_export"]["export_digest"] out_dir = runs_root / run_id / "native_export" / digest[:24] manifest = json.loads( (out_dir / "manifest.json").read_text(encoding="utf-8")) payload_bytes = (out_dir / "payload.json").read_bytes() before = table_hashes(ledger) ref = next(k for k in manifest["artifact_references"] if k.endswith("/production_report")) task, name = ref.rsplit("/", 1) path = runs_root / run_id / "results" / task / (name + ".json") raw = path.read_bytes() # ---- 必要性独立证据(复审 necessary_report_basis.json 同源): # done expand + 已登记提交记录 + 事件 + 原生 payload 实际消费 ---- row = ledger.conn.execute( "SELECT action_id, action_kind, status FROM search_actions" " WHERE run_id = ? AND task_key = ?", (run_id, task)).fetchone() assert row is not None and row["action_kind"] == "expand_hypothesis" assert row["status"] == "done" commit = ledger.conn.execute( "SELECT commit_kind, event_id FROM search_commit_records" " WHERE action_id = ?", (row["action_id"],)).fetchone() assert commit is not None and commit["commit_kind"] == "event_committed" assert commit["event_id"] payload = json.loads(payload_bytes) assert any(r.get("task_key") == task for r in payload["audit_production_reports"]) native_key = manifest["authority_references"]["native_result_task_key"] native_path = runs_root / run_id / "results" / native_key / \ "native_result.json" native_sha_before = hashlib.sha256( native_path.read_bytes()).hexdigest() # ---- 变体注入 ---- if mode == "corrupt": bad = json.loads(raw) bad["payload"]["codex_corrupt_dependency"] = True path.write_text(canonical_json(bad) + "\n", encoding="utf-8") if mode == "missing": path.unlink() # 原 digest 读:引用仍在 ⇒ 逐行校验拒(坏/缺);intact 则通过 if mode == "intact": read_native_export(ledger, runs_root / run_id, digest) else: with pytest.raises(NativeExportContractError) as excinfo: read_native_export(ledger, runs_root / run_id, digest) assert excinfo.value.detail["kind"] == "export_reference_mismatch" assert excinfo.value.detail["artifact"] == ref # ---- 删 manifest 同引用 + 自洽重算新 digest(DB/native 不改) ---- mutated = json.loads(json.dumps(manifest)) mutated["artifact_references"].pop(ref) new_digest, new_dir = _repackage( runs_root / run_id, mutated, payload_bytes) assert new_digest != digest with pytest.raises(NativeExportContractError) as excinfo: read_native_export(ledger, runs_root / run_id, new_digest) detail = excinfo.value.detail assert detail["kind"] == "export_reference_mismatch" if mode == "corrupt": # 坏文件在集合闭合枚举侧先撞 H07 完整性拒(artifact 级; # 先于集合比对 —— 与旧语义一致:坏必要 artifact 不静默跳过) assert detail.get("artifact") == ref assert detail.get("artifact_error_kind") else: assert detail["check"] == "necessary_artifact_reference_set_closure" assert ref in detail["omitted_necessary_refs"] > assert detail["necessary_basis"][ref] == \ ^^^^^^^^^^^^^^^^^^^^^^^^^ "payload_audit_production_report_consumed" E KeyError: 'necessary_basis'
