@pytest.mark.parametrize("mode", [ pytest.param("export_schema", id="unknown_export_schema"), pytest.param("contract_profile", id="unknown_contract_profile"), pytest.param("native_result", id="unknown_native_result"), pytest.param("native_result_missing", id="missing_native_result"), ]) def test_c04_unknown_source_version_no_ledger_refused( tmp_path: Path, mode: str) -> None: """C04 主反例(复审 R2 §4 两最小案 + native_result 版本变体): 只改真实引用来源 manifest 的 schema_version / contract_versions. profile,或 native payload 的 native_result_version(UNKNOWN/ 缺失 + 自洽重算 content_digest),payload 其余字节/DB/steps 均 不变 ⇒ **无 ledger 投影首读先拒**(v3_native_source_version_ unknown,先于当前 adapter 解释内容,与有 ledger/构建共用登记 源);有 ledger 经原生首消费拒;原生读取拒;原文件保全。""" run_id = f"c04r2-{mode}" runs_root, out = _full_fixture(tmp_path, run_id) ledger = ledger_for(runs_root, run_id) run_dir = runs_root / run_id digest = out["native_export"]["export_digest"] projection_digest = out["v3_projection"]["projection_digest"] out_dir = run_dir / "native_export" / digest[:24] manifest = json.loads( (out_dir / "manifest.json").read_text(encoding="utf-8")) projection = json.loads( (run_dir / "v3_projection" / projection_digest[:24] / "projection.json").read_text(encoding="utf-8")) steps_before = projection["route"]["steps"] before = table_hashes(ledger) verified = read_native_export(ledger, run_dir, digest) original_payload_bytes = (out_dir / "payload.json").read_bytes() original_manifest_bytes = (out_dir / "manifest.json").read_bytes() native = verified["payload"] source_payload = json.loads(json.dumps(native)) mutated_manifest = json.loads(json.dumps(manifest)) expected_problem = { "export_schema": "manifest_schema_version", "contract_profile": "contract_versions:profile", "native_result": "payload_native_result_version", "native_result_missing": "payload_native_result_version", }[mode] if mode == "export_schema": mutated_manifest["schema_version"] = "ppv1-native-export-UNKNOWN" if mode == "contract_profile": mutated_manifest["contract_versions"]["profile"] = \ "ppv1-profile-UNKNOWN" if mode in ("native_result", "native_result_missing"): if mode == "native_result": source_payload["native_result_version"] = \ "ppv1-native-result-UNKNOWN" else: source_payload.pop("native_result_version", None) source_payload.pop("content_digest", None) source_payload["content_digest"] = content_hash(source_payload) mutated_manifest["content_digest"] = \ source_payload["content_digest"] source_bytes = (canonical_json(source_payload) + "\n").encode("utf-8") mutated_manifest["payload_sha256"] = \ hashlib.sha256(source_bytes).hexdigest() new_digest, _ = _repackage(run_dir, mutated_manifest, source_bytes) new_projection_digest = _resealed_projection( run_dir, projection, export_digest=new_digest, content_digest=source_payload["content_digest"], payload_sha=mutated_manifest["payload_sha256"]) # ---- 无 ledger 首读:先拒(父来源版本门,先于 adapter 解释) ---- > with pytest.raises(V3ProjectionContractError) as excinfo: E Failed: DID NOT RAISE V3ProjectionContractError
